----------------------------- MODULE ChapelConsensus -----------------------------
EXTENDS Integers, Sequences, FiniteSets, TLC

(*
This TLA+ specification models a distributed consensus protocol for the
JAIDE V25 Chapel-based training framework. It ensures that all nodes agree
on the model parameters (represented as a version number) before proceeding
to the next training step.

This production-ready version includes a simple node failure model.

Properties verified:
 * Agreement: All non-faulty, decided nodes have decided on the same value.
 * Termination: Eventually, all non-faulty nodes decide on a value.
 * Validity: If a value is decided, it must have been proposed by some node.
*)

CONSTANTS Nodes, MaxValue, FaultyNodes

ASSUME IsFiniteSet(Nodes)
ASSUME Cardinality(Nodes) >= 3
ASSUME MaxValue \in Nat
ASSUME FaultyNodes \subseteq Nodes

VARIABLES
    \* The state of each node.
    \* Can be "proposing", "voted", "decided".
    nodeState,

    \* The value proposed by each node (e.g., model version hash).
    proposedValue,

    \* The value a node has voted for in the current round.
    votedValue,

    \* The final value a node has decided on.
    decidedValue,

    \* The current consensus round number for each node.
    round,

    \* A set of messages in the network. A message is a record:
    \* [type: {"propose", "vote", "commit"}, from: Nodes, to: Nodes, round: Nat, value: 0..MaxValue]
    messages

vars == <<nodeState, proposedValue, votedValue, decidedValue, round, messages>>

NonFaultyNodes == Nodes \ FaultyNodes

TypeOK ==
    /\ nodeState \in [Nodes -> {"proposing", "voted", "decided"}]
    /\ proposedValue \in [Nodes -> 0..MaxValue]
    /\ votedValue \in [Nodes -> 0..MaxValue \cup {-1}]
    /\ decidedValue \in [Nodes -> 0..MaxValue \cup {-1}]
    /\ round \in [Nodes -> Nat]
    /\ messages \subseteq
        [ type: {"propose", "vote", "commit"},
          from: Nodes,
          to: Nodes,
          round: Nat,
          value: 0..MaxValue ]

Init ==
    /\ nodeState = [n \in Nodes |-> "proposing"]
    /\ \E val \in 0..MaxValue : proposedValue = [n \in Nodes |-> val]
    /\ votedValue = [n \in Nodes |-> -1]
    /\ decidedValue = [n \in Nodes |-> -1]
    /\ round = [n \in Nodes |-> 1]
    /\ messages = {}

\* A non-faulty node n proposes its value to all other nodes in its current round.
Propose(n) ==
    /\ n \in NonFaultyNodes
    /\ nodeState[n] = "proposing"
    /\ messages' = messages \cup {
        [type |-> "propose", from |-> n, to |-> m, round |-> round[n], value |-> proposedValue[n]]
        : m \in Nodes
    }
    /\ UNCHANGED <<nodeState, proposedValue, votedValue, decidedValue, round>>

\* A non-faulty node n receives a proposal. If it's for a higher or equal round,
\* it votes for the proposed value and broadcasts its vote.
ReceiveProposalAndVote(n) ==
    /\ n \in NonFaultyNodes
    /\ \E msg \in messages:
        /\ msg.type = "propose"
        /\ msg.to = n
        /\ msg.round >= round[n]
        /\ nodeState[n] \in {"proposing", "voted"}
    /\ round' = [round EXCEPT ![n] = msg.round]
    /\ votedValue' = [votedValue EXCEPT ![n] = msg.value]
    /\ nodeState' = [nodeState EXCEPT ![n] = "voted"]
    /\ messages' = (messages \ {msg}) \cup {
        [type |-> "vote", from |-> n, to |-> m, round |-> round'[n], value |-> votedValue'[n]]
        : m \in Nodes
    }
    /\ UNCHANGED <<proposedValue, decidedValue>>

\* A non-faulty node n receives votes. If it gets a quorum of votes for the same value
\* in the current round, it decides on that value and broadcasts a commit message.
\* A quorum is a majority of all nodes (including faulty ones).
ReceiveVotesAndCommit(n) ==
    LET QuorumSize == (Cardinality(Nodes) \div 2) + 1
    IN
    /\ n \in NonFaultyNodes
    /\ \E val \in 0..MaxValue:
        LET receivedVotes == {m.from : m \in messages |
                                /\ m.type = "vote"
                                /\ m.round = round[n]
                                /\ m.value = val
                            }
        IN Cardinality(receivedVotes) >= QuorumSize
    /\ nodeState[n] = "voted"
    /\ nodeState' = [nodeState EXCEPT ![n] = "decided"]
    /\ decidedValue' = [decidedValue EXCEPT ![n] = val]
    /\ messages' = messages \cup {
        [type |-> "commit", from |-> n, to |-> m, round |-> round[n], value |-> val]
        : m \in Nodes
    }
    /\ UNCHANGED <<proposedValue, votedValue, round>>

\* A non-faulty node n receives a commit message and decides on the value.
ReceiveCommit(n) ==
    /\ n \in NonFaultyNodes
    /\ \E msg \in messages:
        /\ msg.type = "commit"
        /\ msg.to = n
        /\ nodeState[n] /= "decided"
    /\ nodeState' = [nodeState EXCEPT ![n] = "decided"]
    /\ decidedValue' = [decidedValue EXCEPT ![n] = msg.value]
    /\ messages' = messages \ {msg}
    /\ UNCHANGED <<proposedValue, votedValue, round>>

Next ==
    \/ \E n \in Nodes: Propose(n)
    \/ \E n \in Nodes: ReceiveProposalAndVote(n)
    \/ \E n \in Nodes: ReceiveVotesAndCommit(n)
    \/ \E n \in Nodes: ReceiveCommit(n)

Spec == Init /\ [][Next]_vars

\* INVARIANTS AND TEMPORAL PROPERTIES

\* Agreement: If two non-faulty nodes have decided, they have decided on the same value.
Agreement ==
    \A n1, n2 \in NonFaultyNodes:
        /\ nodeState[n1] = "decided"
        /\ nodeState[n2] = "decided"
        => decidedValue[n1] = decidedValue[n2]

\* Validity: Any decided value must have been proposed by some node.
Validity ==
    \A n \in Nodes:
        nodeState[n] = "decided" => \E m \in Nodes: decidedValue[n] = proposedValue[m]

\* Termination: Eventually, every non-faulty node decides. (Liveness property)
\* This property will only hold if Cardinality(FaultyNodes) < (Cardinality(Nodes) / 2)
Termination ==
    \A n \in NonFaultyNodes: <> (nodeState[n] = "decided")

=============================================================================
