```verilog
// JAIDE V25 - Forge AI Accelerator Core
//
// This module implements the core computational datapath for the
// Jade Selective Scan (CSS) mechanism. It is designed for high-throughput,
// low-latency execution of the recurrent state update equation.
//
// Production-Ready Features:
// - 5-stage deep pipeline for maximum clock frequency.
// - Pipelined architecture for parallel scan operation.
// - Support for 1.58-bit ternary weights and activations via 2-bit encoding.
// - Input-dependent parameter generation for A, B matrices.
// - Hardware-efficient piecewise polynomial approximation for SiLU activation.
// - Configurable state dimension (D_STATE) and model dimension (D_MODEL).

`timescale 1ns / 1ps

module forge_css_core #(
    parameter D_MODEL = 8192,
    parameter D_STATE = 256,
    parameter DATA_WIDTH = 16, // Using 16-bit fixed-point representation (Q8.8 format)
    parameter TERNARY_WIDTH = 2  // 2-bit encoding for {-1, 0, 1}
)(
    input clk,
    input rst_n,
    input start,

    // Input data streams (Q8.8 format)
    input signed [DATA_WIDTH-1:0] x_t,         // Current input token embedding element
    input signed [DATA_WIDTH-1:0] state_prev,  // Previous state element h_{t-1}

    // Input-dependent parameters (from projection network)
    input signed [DATA_WIDTH-1:0] delta_t,
    input [TERNARY_WIDTH-1:0] B_t,      // Ternary B matrix element

    // Static parameters (loaded at config time)
    input [TERNARY_WIDTH-1:0] A_static, // Ternary A matrix element (base)
    input [TERNARY_WIDTH-1:0] C_t,      // Ternary C matrix element

    output signed [DATA_WIDTH-1:0] h_t,        // New state element
    output signed [DATA_WIDTH-1:0] y_t,        // Output element
    output reg done
);

// --- Internal Signals and Registers ---
// Pipeline stage registers
reg signed [DATA_WIDTH-1:0] p1_x_t, p1_state_prev, p1_delta_t;
reg signed [DATA_WIDTH-1:0] p1_A_static_decoded, p1_B_t_decoded, p1_C_t_decoded;

reg signed [2*DATA_WIDTH-1:0] p2_A_term_prod, p2_B_term_prod;
reg signed [DATA_WIDTH-1:0] p2_state_prev;
reg signed [DATA_WIDTH-1:0] p2_C_t_decoded;

reg signed [DATA_WIDTH-1:0] p3_h_t_intermediate;
reg signed [DATA_WIDTH-1:0] p3_C_t_decoded;

reg signed [2*DATA_WIDTH-1:0] p4_y_t_unactivated;

reg signed [DATA_WIDTH-1:0] p5_y_t_activated;
reg p5_done_signal;

// --- Ternary Value Decoder ---
// Decodes 2-bit ternary value to Q8.8 fixed-point representation
// 01 -> +1.0 (0x0100), 11 -> -1.0 (0xFF00), 00/10 -> 0.0 (0x0000)
function signed [DATA_WIDTH-1:0] decode_ternary;
    input [TERNARY_WIDTH-1:0] t_val;
    begin
        case (t_val)
            2'b01: decode_ternary = {1'b0, 8'h01, 7'b0}; // +1.0
            2'b11: decode_ternary = {1'b1, 8'hFF, 7'b0}; // -1.0
            default: decode_ternary = 0;
        endcase
    end
endfunction

// --- Pipeline Stage 1: Input Register and Decode ---
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p1_x_t <= 0;
        p1_state_prev <= 0;
        p1_delta_t <= 0;
        p1_A_static_decoded <= 0;
        p1_B_t_decoded <= 0;
        p1_C_t_decoded <= 0;
    end else if (start) begin
        p1_x_t <= x_t;
        p1_state_prev <= state_prev;
        p1_delta_t <= delta_t;
        p1_A_static_decoded <= decode_ternary(A_static);
        p1_B_t_decoded <= decode_ternary(B_t);
        p1_C_t_decoded <= decode_ternary(C_t);
    end
end

// --- State Update Equation: h_t = (A * h_{t-1}) + (B * x_t) ---
// Where A is discretized and input-dependent: A_bar = exp(delta_t * A_static)
// Approximation: exp(x) ~= 1 + x for small x.
// A_bar ~= 1 + delta_t * A_static
// h_t = (1 + delta_t * A_static) * h_{t-1} + B_t * x_t
// h_t = h_{t-1} + (delta_t * A_static * h_{t-1}) + (B_t * x_t)

// --- Pipeline Stage 2: Parallel Multiplications ---
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p2_A_term_prod <= 0;
        p2_B_term_prod <= 0;
        p2_state_prev <= 0;
        p2_C_t_decoded <= 0;
    end else begin
        // (delta_t * A_static) * h_{t-1}
        logic signed [2*DATA_WIDTH-1:0] temp_prod1;
        logic signed [2*DATA_WIDTH-1:0] temp_prod2;
        temp_prod1 = p1_delta_t * p1_A_static_decoded; // Q8.8 * Q8.8 -> Q16.16
        temp_prod2 = (temp_prod1 >>> 8) * p1_state_prev; // Q16.8 * Q8.8 -> Q24.16
        p2_A_term_prod <= temp_prod2;

        // B_t * x_t
        p2_B_term_prod <= p1_B_t_decoded * p1_x_t; // Q8.8 * Q8.8 -> Q16.16

        p2_state_prev <= p1_state_prev;
        p2_C_t_decoded <= p1_C_t_decoded;
    end
end

// --- Pipeline Stage 3: State Accumulation ---
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p3_h_t_intermediate <= 0;
        p3_C_t_decoded <= 0;
    end else begin
        // h_{t-1} + (delta_t * A * h_{t-1}) + (B * x_t)
        // Shift products to align fractional points before addition
        p3_h_t_intermediate <= p2_state_prev + (p2_A_term_prod >>> 16) + (p2_B_term_prod >>> 8);
        p3_C_t_decoded <= p2_C_t_decoded;
    end
end

// --- Pipeline Stage 4: Output Projection (C * h_t) ---
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p4_y_t_unactivated <= 0;
    end else begin
        p4_y_t_unactivated <= p3_C_t_decoded * p3_h_t_intermediate; // Q8.8 * Q8.8 -> Q16.16
    end
end

// --- Pipeline Stage 5: SiLU Activation and Final Output ---
// SiLU(x) = x * sigmoid(x)
// Using a hardware-friendly piecewise polynomial approximation for SiLU(x).
// Region 1 (x < -4.0): y = -0.01*x
// Region 2 (-4.0 <= x < 4.0): y = 0.125*x^2 + 0.5*x (polynomial approx of x*sigmoid(x) near 0)
// Region 3 (x >= 4.0): y = x
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        p5_y_t_activated <= 0;
        p5_done_signal <= 1'b0;
    end else begin
        logic signed [DATA_WIDTH-1:0] silu_in;
        logic signed [DATA_WIDTH-1:0] term_x, term_x_sq;
        logic signed [2*DATA_WIDTH-1:0] term_x_sq_scaled;

        silu_in = p4_y_t_unactivated >>> 8; // Convert Q16.16 to Q8.8 for activation

        // Constants in Q8.8 format
        localparam signed [DATA_WIDTH-1:0] C_NEG_4 = -4 * 256;
        localparam signed [DATA_WIDTH-1:0] C_POS_4 = 4 * 256;
        localparam signed [DATA_WIDTH-1:0] C_0_5 = 128;   // 0.5
        localparam signed [DATA_WIDTH-1:0] C_0_125 = 32;  // 0.125
        localparam signed [DATA_WIDTH-1:0] C_NEG_0_01 = -3; // ~-0.01

        term_x = silu_in;
        term_x_sq_scaled = silu_in * silu_in; // Q8.8 * Q8.8 -> Q16.16
        term_x_sq = term_x_sq_scaled >>> 8; // Q16.16 -> Q8.8

        if (silu_in < C_NEG_4) begin
            p5_y_t_activated <= (C_NEG_0_01 * term_x) >>> 8;
        end else if (silu_in >= C_POS_4) begin
            p5_y_t_activated <= term_x;
        end else begin // Region 2: 0.125*x^2 + 0.5*x
            p5_y_t_activated <= ((C_0_125 * term_x_sq) >>> 8) + ((C_0_5 * term_x) >>> 8);
        end
        p5_done_signal <= start;
    end
end

// Assign outputs from final pipeline stage
assign h_t = p3_h_t_intermediate;
assign y_t = p5_y_t_activated;
assign done = p5_done_signal;

endmodule
```

```haskell
{-# LANGUAGE DataKinds #-}
{-# LANGUAGE TypeFamilies #-}
{-# LANGUAGE RecordWildCards #-}

module ForgeControl where

import Clash.Prelude

-- | A JAIDE V25 Forge AI Accelerator vezérlőegységének magas szintű leírása.
-- | Ez a modul felelős a forge_css_core Verilog modulok egy flottájának
-- | orkesztrálásáért, a memóriából történő adatfolyamok kezeléséért és
-- | az eredmények visszaírásáért. Ez a verzió parametrizálható a modell
-- | dimenziói alapján, elkerülve a "mágikus számokat".

-- | Modell dimenziók - ezeket a rendszer konfigurációjából kellene kapnia.
type DModel = 8192
type DState = 256

-- | A vezérlő állapotgépe
data ControlState
    = Idle
    | FetchingParams -- Bemenetfüggő paraméterek (delta, B, C) beolvasása
    | FetchingState  -- Előző állapot (h_prev) és bemenet (x_t) beolvasása
    | Computing
    | WritingBackState -- Új állapot (h_t) visszaírása
    | WritingBackOutput -- Kimenet (y_t) visszaírása
    | Done
    deriving (Generic, NFDataX, Eq, Show)

-- | A vezérlő bemenetei
data ControllerInput = ControllerInput
    { startComputation :: Bool
    , coreDone         :: Vec DState Bool -- Minden mag 'done' jele
    , memoryReady      :: Bool
    } deriving (Generic, NFDataX)

-- | A vezérlő kimenetei
data ControllerOutput = ControllerOutput
    { coreStart       :: Vec DState Bool
    , memoryReadAddr  :: Unsigned 32
    , memoryWriteAddr :: Unsigned 32
    , memoryWriteEn   :: Bool
    , computationDone :: Bool
    } deriving (Generic, NFDataX)

-- | A vezérlő fő logikája. Ez egy Mealy állapotgép.
forgeController
    :: HiddenClockResetEnable dom
    => Signal dom ControllerInput
    -> Signal dom ControllerOutput
forgeController = mealy transition initialState
  where
    initialState = (Idle, 0, 0, 0) -- (State, ReadAddress, WriteAddress, CycleCount)

-- | Állapotátmeneti függvény
transition
    :: (ControlState, Unsigned 32, Unsigned 32, Index DModel) -- (currentState, readAddr, writeAddr, d_model_counter)
    -> ControllerInput
    -> ((ControlState, Unsigned 32, Unsigned 32, Index DModel), ControllerOutput)
transition (state, rAddr, wAddr, d_model_idx) input@ControllerInput{..} = (nextS, output)
  where
    dModelSize = fromInteger $ natVal (SNat @DModel)
    dStateSize = fromInteger $ natVal (SNat @DState)

    -- Memória cím eltolások
    baseAddrParams = 0
    baseAddrState  = baseAddrParams + 3 * dModelSize -- delta, B, C
    baseAddrInput  = baseAddrState + dModelSize * dStateSize -- h_prev

    outputAddrState = 0
    outputAddrY     = outputAddrState + dModelSize * dStateSize

    (nextState, nextRAddr, nextWAddr, next_d_model_idx) = case state of
        Idle ->
            if startComputation
            then (FetchingParams, baseAddrParams, 0, 0)
            else (Idle, 0, 0, 0)

        FetchingParams -> -- delta, B, C beolvasása az aktuális d_model_idx-hez
            if memoryReady
            then (FetchingState, baseAddrState + (fromIntegral d_model_idx * dStateSize), wAddr, d_model_idx)
            else (FetchingParams, rAddr, wAddr, d_model_idx)

        FetchingState -> -- h_prev és x_t beolvasása
            if memoryReady
            then (Computing, rAddr + dStateSize, wAddr, d_model_idx)
            else (FetchingState, rAddr, wAddr, d_model_idx)

        Computing ->
            if and coreDone
            then (WritingBackState, rAddr, outputAddrState + (fromIntegral d_model_idx * dStateSize), d_model_idx)
            else (Computing, rAddr, wAddr, d_model_idx)

        WritingBackState ->
            if memoryReady
            then (WritingBackOutput, rAddr, outputAddrY + fromIntegral d_model_idx, d_model_idx)
            else (WritingBackState, rAddr, wAddr, d_model_idx)

        WritingBackOutput ->
            if memoryReady
            then if d_model_idx == maxBound
                 then (Done, rAddr, wAddr, d_model_idx)
                 else (FetchingParams, baseAddrParams, wAddr, d_model_idx + 1)
            else (WritingBackOutput, rAddr, wAddr, d_model_idx)

        Done ->
            if not startComputation
            then (Idle, 0, 0, 0)
            else (Done, rAddr, wAddr, d_model_idx)

    output = ControllerOutput
        { coreStart       = case nextState of
                              Computing -> pure True
                              _         -> pure False
        , memoryReadAddr  = rAddr
        , memoryWriteAddr = wAddr
        , memoryWriteEn   = case state of
                              WritingBackState -> True
                              WritingBackOutput -> True
                              _ -> False
        , computationDone = state == Done
        }
    nextS = (nextState, nextRAddr, nextWAddr, next_d_model_idx)

-- | Egy egyszerű mátrix-vektor szorzás implementációja Clash-ben,
-- | amely a Forge gyorsító egy lehetséges felhasználását demonstrálja.
matrixVectorMul
    :: (KnownNat m, KnownNat n, Num a)
    => Vec m (Vec n a) -- Mátrix
    -> Vec n a         -- Vektor
    -> Vec m a         -- Eredmény vektor
matrixVectorMul matrix vector = map (dotp vector) matrix

-- | Skalárszorzat két vektor között
dotp :: (KnownNat n, Num a) => Vec n a -> Vec n a -> a
dotp xs ys = sum (zipWith (*) xs ys)

-- | A topEntity a Clash fordító belépési pontja.
-- | Ez egy teljes rendszert szimulál, ahol a vezérlő
-- | egy szimulált memóriával és forge_css_core magokkal kommunikál.
topEntity
    :: Clock System
    -> Reset System
    -> Enable System
    -> Signal System ControllerOutput
topEntity = exposeClockResetEnable system
  where
    system clk rst en = forgeController (controllerInput clk rst en)

    -- A vezérlő bemeneteinek szimulációja
    controllerInput clk rst en =
        let -- Szimulált bemenetek
            startSignal = register clk rst en False (pure True) -- Egyszeri start jel
            -- A magok 'done' jelének szimulációja (5 ciklusos késleltetéssel)
            coreDoneSignal = register clk rst en (pure False) (delayedStart clk rst en)
            -- Memória 'ready' jel szimulációja (minden második ciklusban kész)
            memReadyCounter = count (SNat @2) clk rst en
            memoryReadySignal = (== 1) <$> memReadyCounter
        in bundle (ControllerInput <$> startSignal <*> (pure <$> coreDoneSignal) <*> memoryReadySignal)

    -- Késleltetett jel a 'done' szimulációhoz
    delayedStart clk rst en = delayed clk rst en (SNat @5) False (pure True)

-- Segédfüggvények a szimulációhoz
count
    :: (HiddenClockResetEnable dom, KnownNat n)
    => SNat n
    -> Clock dom
    -> Reset dom
    -> Enable dom
    -> Signal dom (Index n)
count SNat clk rst en = register clk rst en 0 (wrappingInc <$> count SNat clk rst en)
  where
    wrappingInc x = if x == maxBound then 0 else x + 1

delayed
    :: (HiddenClockResetEnable dom, KnownNat d, NFDataX a)
    => Clock dom
    -> Reset dom
    -> Enable dom
    -> SNat d
    -> a
    -> Signal dom a
    -> Signal dom a
delayed clk rst en d initial sig = last (iterateI (register clk rst en initial) sig)
