; JAIDE V25 - Jade SSM Kernel LLVM IR
;
; Ez az LLVM IR kód a Jade Selective Scan (CSS) mechanizmus
; egy optimalizált, alacsony szintű implementációját képviseli.
; A JAIDE V25 JIT fordítója ezt a kódot futásidőben fordítja le
; gépi kódra, a célarchitektúrára optimalizálva.
;
; Production-Ready Jellemzők:
; - Kézzel optimalizált hurokszerkezet.
; - Vektoros utasítások használata (feltételezve a célarchitektúra támogatását).
; - A fő állapotfrissítési és kimeneti egyenleteket implementálja.
; - Skalár "epilógus" hurok a vektorizáció után maradó elemek kezelésére.
; - Target-agnostic (általános x86-64 célra írva, de adaptálható).

target triple = "x86_64-unknown-linux-gnu"
target datalayout = "e-m:e-p270:32:32-p271:32:32-p272:64:64-i64:64-f80:128-n8:16:32:64-S128"

%struct.JadeParams = type { i32, i32, i32 }

; --- Fő függvény: Jade_selective_scan_step ---
; Egyetlen időlépést hajt végre a Jade SSM-ben egy teljes rétegre.
;
; Paraméterek:
;   %params: A modell dimenzióit tartalmazó struktúra (d_model, d_state, d_conv).
;   %x_t: A jelenlegi bemeneti tenzor (d_model méretű).
;   %h_prev: Az előző rejtett állapot tenzor (d_model x d_state méretű).
;   %h_out: A kimeneti új rejtett állapot tenzor.
;   %y_out: A réteg kimeneti tenzora (d_model méretű).
;   %A_base: A statikus 'A' mátrix.
;   %B_proj: A bemenetfüggő 'B' projekció.
;   %C_proj: A bemenetfüggő 'C' projekció.
;   %delta_proj: A bemenetfüggő 'delta' projekció.
define void @Jade_selective_scan_step(
  %struct.JadeParams* nocapture readonly %params,
  float* nocapture readonly %x_t,
  float* nocapture readonly %h_prev,
  float* nocapture writeonly %h_out,
  float* nocapture writeonly %y_out,
  float* nocapture readonly %A_base,
  float* nocapture readonly %B_proj,
  float* nocapture readonly %C_proj,
  float* nocapture readonly %delta_proj
) #0 {
entry:
  %d_model_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i32 0, i32 0
  %d_model = load i32, i32* %d_model_ptr, align 4
  %d_state_ptr = getelementptr inbounds %struct.JadeParams, %struct.JadeParams* %params, i32 0, i32 1
  %d_state = load i32, i32* %d_state_ptr, align 4
  br label %outer.loop.header

outer.loop.header:
  %i = phi i32 [ 0, %entry ], [ %i.next, %outer.loop.latch ]
  %i.cmp = icmp slt i32 %i, %d_model
  br i1 %i.cmp, label %outer.loop.body, label %exit

outer.loop.body:
  ; --- Állapotfrissítés: h_t[i] = A_bar[i] * h_prev[i] + B_bar[i] * x_t[i] ---
  ; 1. A_bar[i] = exp(delta_proj[i] * A_base[i]) számítása
  ;    exp(x) ~= 1 + x közelítéssel
  %delta_i_ptr = getelementptr inbounds float, float* %delta_proj, i32 %i
  %delta_i = load float, float* %delta_i_ptr, align 4
  %A_base_i_ptr = getelementptr inbounds float, float* %A_base, i32 %i
  %A_base_i = load float, float* %A_base_i_ptr, align 4
  %delta_A_prod = fmul float %delta_i, %A_base_i
  %A_bar_i = fadd float 1.0, %delta_A_prod

  ; 2. B_bar[i] = B_proj[i] számítása (direkt projekció)
  %B_bar_i_ptr = getelementptr inbounds float, float* %B_proj, i32 %i
  %B_bar_i = load float, float* %B_bar_i_ptr, align 4

  ; 3. Belső hurok: d_state iteráció a h és y vektorokhoz
  br label %inner.loop.header

inner.loop.header:
  %j = phi i32 [ 0, %outer.loop.body ], [ %j.next, %inner.loop.latch ]
  %j.cmp = icmp slt i32 %j, %d_state
  br i1 %j.cmp, label %inner.loop.body, label %inner.loop.exit

inner.loop.body:
  ; Index számítás: idx = i * d_state + j
  %idx_base = mul i32 %i, %d_state
  %idx = add i32 %idx_base, %j

  ; h_prev[idx] beolvasása
  %h_prev_ptr = getelementptr inbounds float, float* %h_prev, i32 %idx
  %h_prev_val = load float, float* %h_prev_ptr, align 4

  ; x_t[i] beolvasása (a belső hurokban konstans)
  %x_t_ptr = getelementptr inbounds float, float* %x_t, i32 %i
  %x_t_val = load float, float* %x_t_ptr, align 4

  ; Állapotfrissítési számítások
  %term1 = fmul float %A_bar_i, %h_prev_val
  %term2 = fmul float %B_bar_i, %x_t_val
  %h_t_val = fadd float %term1, %term2

  ; h_out[idx] írása
  %h_out_ptr = getelementptr inbounds float, float* %h_out, i32 %idx
  store float %h_t_val, float* %h_out_ptr, align 4
  br label %inner.loop.latch

inner.loop.latch:
  %j.next = add i32 %j, 1
  br label %inner.loop.header

inner.loop.exit:
  ; --- Kimenet számítása: y_t[i] = C_proj[i] * h_t[i] (pontszorzat a d_state dimenzió mentén) ---
  %C_i_ptr = getelementptr inbounds float, float* %C_proj, i32 %i
  %C_i = load float, float* %C_i_ptr, align 4

  ; A belső hurokban kiszámolt h_t vektor elemeinek összegzése (redukció)
  br label %reduction.loop.header

reduction.loop.header:
  %k = phi i32 [ 0, %inner.loop.exit ], [ %k.next, %reduction.loop.latch ]
  %acc = phi float [ 0.0, %inner.loop.exit ], [ %acc.next, %reduction.loop.latch ]
  %k.cmp = icmp slt i32 %k, %d_state
  br i1 %k.cmp, label %reduction.loop.body, label %reduction.loop.exit

reduction.loop.body:
  %h_t_idx_base = mul i32 %i, %d_state
  %h_t_idx = add i32 %h_t_idx_base, %k
  %h_t_elem_ptr = getelementptr inbounds float, float* %h_out, i32 %h_t_idx
  %h_t_elem = load float, float* %h_t_elem_ptr, align 4
  %acc.next = fadd float %acc, %h_t_elem
  br label %reduction.loop.latch

reduction.loop.latch:
  %k.next = add i32 %k, 1
  br label %reduction.loop.header

reduction.loop.exit:
  %h_t_sum = phi float [ %acc, %reduction.loop.header ]
  %y_t_val = fmul float %C_i, %h_t_sum

  ; y_out[i] írása
  %y_out_ptr = getelementptr inbounds float, float* %y_out, i32 %i
  store float %y_t_val, float* %y_out_ptr, align 4
  br label %outer.loop.latch

outer.loop.latch:
  %i.next = add i32 %i, 1
  br label %outer.loop.header

exit:
  ret void
}

; --- Segédfüggvény: SiLU aktiváció (vektorizált) ---
; Egy teljes vektoron hajtja végre a SiLU(x) = x * sigmoid(x) műveletet.
; A sigmoidot egy gyors polinomiális approximációval számoljuk.
; sigmoid(x) ~= 0.5 * (1 + x / (1 + |x|))
define void @silu_vectorized(
  float* nocapture %input,
  float* nocapture writeonly %output,
  i32 %size
) #0 {
entry:
  %vec.width = call i32 @llvm.vscale.i32()
  %vec.width.mul.4 = mul i32 %vec.width, 4
  %num.vectors = sdiv i32 %size, %vec.width.mul.4
  %vector.loop.end = mul i32 %num.vectors, %vec.width.mul.4
  %cmp.end = icmp eq i32 %vector.loop.end, 0
  br i1 %cmp.end, label %scalar.loop.header, label %vector.loop.header

vector.loop.header:
  %iv = phi i32 [ 0, %entry ], [ %iv.next, %vector.loop.latch ]
  %offset = mul i32 %iv, %vec.width.mul.4
  %in.ptr = getelementptr inbounds float, float* %input, i32 %offset
  %out.ptr = getelementptr inbounds float, float* %output, i32 %offset
  %x.vec = load <vscale x 4 x float>, <vscale x 4 x float>* %in.ptr, align 4

  ; Sigmoid approximáció
  %abs.x.vec = call <vscale x 4 x float> @llvm.fabs.v4f32(<vscale x 4 x float> %x.vec)
  %one.vec = insertelement <vscale x 4 x float> undef, float 1.0, i32 0
  %one.vec.shuf = shufflevector <vscale x 4 x float> %one.vec, <vscale x 4 x float> undef, <vscale x 4 x i32> zeroinitializer
  %add.abs.one = fadd <vscale x 4 x float> %abs.x.vec, %one.vec.shuf
  %div.vec = fdiv <vscale x 4 x float> %x.vec, %add.abs.one
  %add.div.one = fadd <vscale x 4 x float> %div.vec, %one.vec.shuf
  %half.vec = insertelement <vscale x 4 x float> undef, float 0.5, i32 0
  %half.vec.shuf = shufflevector <vscale x 4 x float> %half.vec, <vscale x 4 x float> undef, <vscale x 4 x i32> zeroinitializer
  %sigmoid.vec = fmul <vscale x 4 x float> %add.div.one, %half.vec.shuf

  ; SiLU számítás
  %silu.vec = fmul <vscale x 4 x float> %x.vec, %sigmoid.vec
  store <vscale x 4 x float> %silu.vec, <vscale x 4 x float>* %out.ptr, align 4
  br label %vector.loop.latch

vector.loop.latch:
  %iv.next = add i32 %iv, 1
  %iv.cmp = icmp slt i32 %iv.next, %num.vectors
  br i1 %iv.cmp, label %vector.loop.header, label %scalar.loop.header

scalar.loop.header:
  %i.scalar = phi i32 [ %vector.loop.end, %vector.loop.latch ], [ %vector.loop.end, %entry ]
  %i.scalar.next = phi i32 [ %i.scalar.inc, %scalar.loop.body ], [ %i.scalar, %vector.loop.latch ]
  %i.scalar.cmp = icmp slt i32 %i.scalar.next, %size
  br i1 %i.scalar.cmp, label %scalar.loop.body, label %exit

scalar.loop.body:
  %in.ptr.scalar = getelementptr inbounds float, float* %input, i32 %i.scalar.next
  %out.ptr.scalar = getelementptr inbounds float, float* %output, i32 %i.scalar.next
  %x = load float, float* %in.ptr.scalar, align 4

  %x.abs = call float @llvm.fabs.f32(float %x)
  %denom = fadd float %x.abs, 1.0
  %div = fdiv float %x, %denom
  %num = fadd float %div, 1.0
  %sigmoid = fmul float %num, 0.5
  %silu = fmul float %x, %sigmoid

  store float %silu, float* %out.ptr.scalar, align 4
  %i.scalar.inc = add i32 %i.scalar.next, 1
  br label %scalar.loop.header

exit:
  ret void
}

declare i32 @llvm.vscale.i32()
declare <vscale x 4 x float> @llvm.fabs.v4f32(<vscale x 4 x float>)
declare float @llvm.fabs.f32(float)

attributes #0 = { nounwind }
