include "../framework/vale_prelude.vad"

// This Vale module provides a formally verified implementation of a memory-safe
// message parser for the JAIDE V25 IPC (Inter-Process Communication) fabric.
//
// It guarantees that the parser will never read or write out of bounds,
// preventing a common source of security vulnerabilities and crashes.
// The verification is performed by the Dafny framework.

module ipc_parser

// Procedure to parse a message header from a raw byte buffer.
// The header is assumed to be 16 bytes:
// - 8 bytes: Message ID (u64)
// - 4 bytes: Payload Length (u32)
// - 4 bytes: Message Type (u32)
procedure parse_message_header(
    ghost buffer: seq<byte>,
    inout rdi: nat64, // Input: pointer to buffer start
    out rax: nat64,   // Output: message ID
    out rbx: nat32,   // Output: payload length
    out rcx: nat32    // Output: message type
)
    requires 0 <= rdi;
    requires |buffer| >= rdi + 16; // Precondition: Buffer must be large enough
    modifies rax, rbx, rcx;
    ensures rax == u64(sub(buffer, rdi, 8));     // Postcondition: rax holds the message ID
    ensures rbx == u32(sub(buffer, rdi + 8, 4)); // Postcondition: rbx holds the payload length
    ensures rcx == u32(sub(buffer, rdi + 12, 4));// Postcondition: rcx holds the message type
{
    // Load Message ID (64-bit)
    rax := Mem64[rdi];
    // Load Payload Length (32-bit)
    rbx := Mem32[rdi + 8];
    // Load Message Type (32-bit)
    rcx := Mem32[rdi + 12];
}

// A unified procedure that parses a header, validates payload bounds, and
// on success, returns a pointer to the payload.
// This is a more robust, production-ready function.
procedure parse_and_get_payload_ptr(
    ghost buffer: seq<byte>,
    in rdi: nat64,      // Pointer to buffer start
    in rsi: nat64,      // Total buffer length
    out rax: nat64,     // Output: 0 on failure, pointer to payload on success
    out rbx: nat32      // Output: payload length on success
)
    requires 0 <= rdi;
    requires rdi <= rsi;
    requires |buffer| == rsi;
    modifies rax, rbx;
    ensures rax == 0 ==> // On failure
        !(rdi + 16 <= rsi && rdi + 16 + u64(u32(sub(buffer, rdi + 8, 4))) <= rsi);
    ensures rax != 0 ==> // On success
        rbx == u32(sub(buffer, rdi + 8, 4)) && // rbx has correct length
        rax == rdi + 16 && // rax points to payload
        rax + u64(rbx) <= rsi; // payload is within bounds
{
    // Check if header itself is readable
    var header_end: nat64;
    var carry: bool;
    carry, header_end := Add(rdi, 16);
    if carry || header_end > rsi {
        rax := 0;
        rbx := 0;
        return;
    }

    // Header is safe to read, parse it
    var msg_id: nat64;
    var msg_type: nat32;
    parse_message_header(buffer, rdi, msg_id, rbx, msg_type);

    // Validate payload bounds
    var payload_len: nat64 := rbx;
    var payload_end: nat64;
    carry, payload_end := Add(header_end, payload_len);
    if carry || payload_end > rsi {
        rax := 0;
        // rbx might hold a malicious length, but rax=0 signals failure
        return;
    }

    // Success: payload is within bounds
    rax := header_end; // Pointer to payload
}

// A verified procedure to copy the payload if it's valid.
// This demonstrates using the verified bounds check from the unified function.
procedure copy_verified_payload(
    ghost src_buffer: seq<byte>,
    ghost dst_buffer: seq<byte>,
    in rdi: nat64,      // Pointer to source buffer start
    in rsi: nat64,      // Pointer to destination buffer start
    in rdx: nat64,      // Source buffer total length
    in rcx: nat64       // Destination buffer total length
)
    requires 0 <= rdi && rdi <= rdx;
    requires 0 <= rsi && rsi <= rcx;
    requires |src_buffer| == rdx;
    requires |dst_buffer| == rcx;
    modifies rdi, rsi; // This is a simplification; in reality, it modifies memory
    ensures (exists payload_ptr: nat64, payload_len: nat32 ::
        old(parse_and_get_payload_ptr(src_buffer, rdi, rdx, payload_ptr, payload_len)) &&
        payload_ptr != 0 &&
        u64(payload_len) <= rcx &&
        sub(dst_buffer, rsi, payload_len) == sub(src_buffer, payload_ptr, payload_len)
    );
{
    var payload_ptr: nat64;
    var payload_len: nat32;

    parse_and_get_payload_ptr(src_buffer, rdi, rdx, payload_ptr, payload_len);

    if payload_ptr != 0 {
        var len64: nat64 := payload_len;
        if len64 <= rcx {
            // It's safe to copy
            var count: nat64 := 0;
            while count < len64
                invariant 0 <= count <= len64;
                invariant sub(dst_buffer, rsi, count) == sub(src_buffer, payload_ptr, count);
            {
                var temp_byte: byte;
                temp_byte := Mem8[payload_ptr + count];
                Mem8[rsi + count] := temp_byte;
                count := count + 1;
            }
        }
    }
}
